"use strict";(self.webpackChunkwoocommerce_restaurant_kitchen_pos_doc=self.webpackChunkwoocommerce_restaurant_kitchen_pos_doc||[]).push([[975],{7403(e,t,n){n.r(t),n.d(t,{_pageData:()=>s,default:()=>i});var o=n(641);const a={class:"hint-container important"},s=JSON.parse('{"path":"/kitchen-customer-screen/licence-and-updates.html","title":"Licence and Updates","lang":"en-US","frontmatter":{"title":"Licence and Updates","description":"Activate Kitchen and Customer Screen for Restaurant POS with your purchase code on the Module License screen, read the licence statuses, extend support and receive plugin updates on the WordPress Plugins page."},"git":{},"filePathRelative":"kitchen-customer-screen/licence-and-updates.md"}'),r={name:"licence-and-updates.md"},i=(0,n(6262).A)(r,[["render",function(e,t,n,s,r,i){const d=(0,o.g2)("RouteLink");return(0,o.uX)(),(0,o.CE)("div",null,[t[12]||(t[12]=(0,o.Lk)("h1",{id:"licence-and-updates",tabindex:"-1"},[(0,o.Lk)("a",{class:"header-anchor",href:"#licence-and-updates"},[(0,o.Lk)("span",null,"Licence and Updates")])],-1)),t[13]||(t[13]=(0,o.Lk)("p",null,[(0,o.eW)("Every active Webkul module on a Point of Sale site has to be activated with the "),(0,o.Lk)("strong",null,"purchase code"),(0,o.eW)(" from the order it came from. Kitchen and Customer Screen for Restaurant POS is no exception, and activation is what also turns on plugin updates.")],-1)),(0,o.Lk)("p",null,[t[1]||(t[1]=(0,o.eW)("Do this straight after ",-1)),(0,o.bF)(d,{to:"/kitchen-customer-screen/installation.html"},{default:(0,o.k6)(()=>[...t[0]||(t[0]=[(0,o.eW)("Installation",-1)])]),_:1}),t[2]||(t[2]=(0,o.eW)(", before you start configuring.",-1))]),t[14]||(t[14]=(0,o.Fv)('<h2 id="where-licences-are-managed" tabindex="-1"><a class="header-anchor" href="#where-licences-are-managed"><span>Where licences are managed</span></a></h2><p>Go to <strong>Restaurant POS → License</strong>. Every active Webkul module on the site is listed on one screen, including this one.</p><p><img src="/kitchen-and-customer-screen-for-restaurant-pos/images/kitchen-customer-screen/license-module-status.png" alt="The Module License screen listing RESPOS Kitchen And Customer Screen and the other Webkul modules"></p><table><thead><tr><th>Column</th><th>What it tells you</th></tr></thead><tbody><tr><td><strong>Plugin</strong></td><td>The module name</td></tr><tr><td><strong>Version</strong></td><td>The version installed right now</td></tr><tr><td><strong>Purchase From</strong></td><td>Where the licence came from — <strong>Webkul Store</strong> or <strong>Codecanyon</strong></td></tr><tr><td><strong>Support Till</strong></td><td>The date support runs until, or <strong>Pending</strong> while the module is not activated</td></tr><tr><td><strong>Status</strong></td><td><strong>Activate</strong>, <strong>Approved</strong> or an <strong>Extend Support</strong> button — see below</td></tr></tbody></table><h2 id="the-three-statuses" tabindex="-1"><a class="header-anchor" href="#the-three-statuses"><span>The three statuses</span></a></h2><table><thead><tr><th>Status</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Activate</strong> button</td><td>The module has no valid purchase code yet</td><td>Select <strong>Activate</strong> and enter the purchase code from your order</td></tr><tr><td><strong>Approved</strong></td><td>The module is activated and in support</td><td>Nothing. This is the state you want</td></tr><tr><td><strong>Extend Support</strong> button</td><td>Support has run out</td><td>Select it to renew, then use <strong>Sync Support</strong> to pull the new date in</td></tr></tbody></table><p>After extending support, the <strong>Sync Support</strong> button stays disabled for a few minutes while the store catches up. Hovering it explains how long is left.</p><h2 id="activating-the-module" tabindex="-1"><a class="header-anchor" href="#activating-the-module"><span>Activating the module</span></a></h2><ol><li>Go to <strong>Restaurant POS → License</strong>.</li><li>Find <strong>RESPOS Kitchen And Customer Screen</strong> in the list — that is how this module is named in WordPress.</li><li>Select <strong>Activate</strong> in the Status column.</li><li>Paste the purchase code from your Webkul Store or CodeCanyon order and confirm.</li></ol><p>The screen answers <strong>Purchase Code Saved</strong> when it is accepted. Two things can go wrong:</p><table><thead><tr><th>Message</th><th>Cause</th></tr></thead><tbody><tr><td>Purchase Code is not Correct</td><td>The code does not match this module or this order</td></tr><tr><td>Please provide valid details</td><td>A required field was left empty</td></tr></tbody></table><p>Step by step instructions with pictures, including where to find the code on each store, are in Webkul&#39;s <a href="https://marketplace.webkul.com/knowledgebase/activate-woocommerce-plugin-license-key/" target="_blank" rel="noopener noreferrer">licence activation guide</a>.</p><h2 id="why-activation-matters" tabindex="-1"><a class="header-anchor" href="#why-activation-matters"><span>Why activation matters</span></a></h2><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Leaving a Webkul module unactivated does not just remove support. The Module License screen states it plainly: <strong>all active modules must be activated with valid purchase codes. If any module remains unactivated, customers will be unable to complete the checkout process, and a mandatory activation notice will be displayed in the website footer.</strong></p></div><p>While anything is unactivated, the WordPress admin also shows a standing notice — <em>Webkul Module License Activation Required</em> — with a link to this screen. A user who is not an administrator sees the same notice asking them to contact the administrator instead.</p><h2 id="getting-updates" tabindex="-1"><a class="header-anchor" href="#getting-updates"><span>Getting updates</span></a></h2><p>Activating the licence does not install new versions by itself. How an update reaches you depends on where you bought the module — the <strong>Purchase From</strong> column on the Module License screen shows which applies to you.</p><h3 id="bought-on-codecanyon-update-from-the-plugins-screen" tabindex="-1"><a class="header-anchor" href="#bought-on-codecanyon-update-from-the-plugins-screen"><span>Bought on CodeCanyon: update from the Plugins screen</span></a></h3><p>Connect your Envato account once, and new versions can then be installed from the WordPress <strong>Plugins</strong> screen with one click.</p><ol><li><p><strong>Create an Envato API personal token.</strong> Sign in to <a href="https://build.envato.com/create-token/" target="_blank" rel="noopener noreferrer">build.envato.com</a> with the Envato account that bought the plugin. Name the token, for example <em>WooCommerce Store</em>, and enable exactly these three permissions:</p><ul><li>View and search Envato sites</li><li>Download your purchased items</li><li>List purchases you&#39;ve made</li></ul><p>Accept the terms and select <strong>Create Token</strong>. Copy the token straight away.</p></li><li><p><strong>Save it in WordPress.</strong> Go to <strong>Restaurant POS → License</strong>. Below the module list is the <strong>Envato Token Settings</strong> section. Paste the token into <strong>Envato Token</strong> and select <strong>Save Changes</strong>.</p></li><li><p><strong>Test it.</strong> Select <strong>Test API Connection</strong>. The result beside the button should read <strong>Connected.</strong></p></li><li><p><strong>Update.</strong> When a new version is released, the plugin row on <strong>Plugins → Installed Plugins</strong> shows an notice — <em>There is a new version of RESPOS Kitchen And Customer Screen available.</em> Select <strong>View version … details</strong> to read what changed, then <strong>update now</strong>. The same update is also listed under <strong>Dashboard → Updates</strong>.</p></li></ol><table><thead><tr><th>Result of Test API Connection</th><th>What to do</th></tr></thead><tbody><tr><td>Connected.</td><td>Nothing. Updates will appear on the Plugins screen</td></tr><tr><td>Invalid token.</td><td>The token was mistyped or deleted. Create a new one and save it again</td></tr><tr><td>Token have some required permission missing.</td><td>Create a new token with all three permissions above</td></tr><tr><td>Token have additional permissions.</td><td>The token has more than the three permissions. Create a new token with only those three</td></tr></tbody></table><div class="hint-container note"><p class="hint-container-title">Note</p><p>The <strong>Envato Token Settings</strong> section is shown only when at least one module on the Module License screen was bought on CodeCanyon.</p></div><p>Webkul&#39;s own walkthrough, with pictures of the Envato screens, is <a href="https://marketplace.webkul.com/knowledgebase/get-updates-webkul-modules-directly-on-plugins-page/" target="_blank" rel="noopener noreferrer">How to Get Updates of Webkul Modules Directly on the Plugins page</a>.</p><p>If you would rather not connect a token, download the latest version from <strong>Downloads</strong> in your CodeCanyon account and upload it as described below.</p><h3 id="bought-on-the-webkul-store-download-and-upload" tabindex="-1"><a class="header-anchor" href="#bought-on-the-webkul-store-download-and-upload"><span>Bought on the Webkul Store: download and upload</span></a></h3><p>The Envato token does not apply to a Webkul Store purchase. Download the latest version of the plugin from your account on the <a href="https://store.webkul.com/woocommerce-restaurant-kitchen-pos.html" target="_blank" rel="noopener noreferrer">Webkul Store</a>, then install it over the current one:</p><ol><li>Go to <strong>Plugins → Add New → Upload Plugin</strong>.</li><li>Choose the new zip file and select <strong>Install Now</strong>.</li><li>WordPress notices that the plugin is already installed and compares the two versions. Select <strong>Replace current with uploaded</strong>.</li></ol><p>Your settings, outlets, customer screen artwork and Kitchen User accounts are stored in the database, so they are kept. If you cannot find the download, raise a ticket with Webkul support.</p>',28)),(0,o.Lk)("div",a,[t[8]||(t[8]=(0,o.Lk)("p",{class:"hint-container-title"},"Important",-1)),(0,o.Lk)("p",null,[t[4]||(t[4]=(0,o.eW)("After updating this module, the kitchen web app files in your site root are ",-1)),t[5]||(t[5]=(0,o.Lk)("strong",null,"not",-1)),t[6]||(t[6]=(0,o.eW)(" rewritten automatically. If the installed kitchen app on a tablet shows an old name, colour or icon, deactivate and reactivate the plugin once. See ",-1)),(0,o.bF)(d,{to:"/kitchen-customer-screen/general-settings.html"},{default:(0,o.k6)(()=>[...t[3]||(t[3]=[(0,o.eW)("General Settings",-1)])]),_:1}),t[7]||(t[7]=(0,o.eW)(".",-1))])]),t[15]||(t[15]=(0,o.Lk)("h2",{id:"next-step",tabindex:"-1"},[(0,o.Lk)("a",{class:"header-anchor",href:"#next-step"},[(0,o.Lk)("span",null,"Next step")])],-1)),(0,o.Lk)("p",null,[t[10]||(t[10]=(0,o.eW)("Continue with ",-1)),(0,o.bF)(d,{to:"/kitchen-customer-screen/real-time-connection.html"},{default:(0,o.k6)(()=>[...t[9]||(t[9]=[(0,o.eW)("Real Time Connection",-1)])]),_:1}),t[11]||(t[11]=(0,o.eW)(".",-1))])])}]])}}]);